const M=window.FindsModel,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format(n),norm=s=>String(s).toLowerCase().replace(/[^a-z0-9]/g,'').replace(/ggdb|ggs/g,'goldengoose');
const read=(key,fallback,storage=localStorage)=>{try{return JSON.parse(storage.getItem(key))??fallback}catch{return fallback}};
let syncController;
let favorites=read('finds-saved-v2',{}),navigation=read('finds-navigation-v3',read('finds-navigation-v2',{view:'mine',views:{}},sessionStorage)),view=['mine','all','saved','hidden','hauls'].includes(navigation.view)?navigation.view:'mine',category='',visible=40,catalog,groups=[],groupMap=new Map(),detailKey='',imageIndex=0,toastTimer;
if(!favorites||Array.isArray(favorites)||typeof favorites!=='object')favorites={};navigation.views??={};
let planning=read('finds-planning-v1',{hidden:{},hauls:{}});if(!planning||typeof planning!=='object'||Array.isArray(planning))planning={};planning.hidden??={};planning.hauls??={};
function savePlanning(){try{localStorage.setItem('finds-planning-v1',JSON.stringify(planning));syncController?.capture();return true}catch{toast('Speichern fehlgeschlagen. Bitte Sammlung exportieren.');return false}}
function productFor(key){return groupMap.get(key)||favorites[key]||planning.hidden[key]}
function hideProduct(key){const g=productFor(key);if(!g)return;const haulItems={};for(const [id,h] of Object.entries(planning.hauls)){if(h.items?.[key]){haulItems[id]=h.items[key];delete h.items[key];h.costsStale=true}}planning.hidden[key]={...g,haulItems,hiddenAt:new Date().toISOString()};savePlanning();if(detailKey===key)closeDetail();render(false);toast('Produkt ausgeblendet.');const undo=document.createElement('button');undo.textContent='Rückgängig';undo.dataset.restore=key;$('#toast').append(' ',undo);clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6000)}
function restoreProduct(key){for(const [id,item] of Object.entries(planning.hidden[key]?.haulItems||{})){const h=planning.hauls[id]??={items:{},shipping:'',packing:'',domestic:'',fees:'',taxes:''};if(!h.items[key]){h.items[key]=item;h.costsStale=true}}delete planning.hidden[key];savePlanning();render(false);toast('Produkt wird wieder angezeigt.')}
function addToHaul(key,index){const g=productFor(key),offer=g?.offers[index],agent=offer&&M.agent(offer);if(!agent)return;const haul=planning.hauls[agent.id]??={items:{},shipping:'',packing:'',domestic:'',fees:'',taxes:''};const old=haul.items[g.key];if(!old&&Object.keys(haul.items).length)haul.costsStale=true;haul.items[g.key]={key:g.key,name:g.name,image:g.images[0]||'',offer:{...offer},quantity:old?.quantity||1,addedAt:new Date().toISOString()};savePlanning();render(false);renderDetail();toast('Im '+agent.name+'-Haul gespeichert.')}
function renderHauls(){const entries=Object.entries(planning.hauls).filter(([,h])=>Object.keys(h.items||{}).length);$('#hauls').innerHTML='<p>Jeder Haul gehört zu genau einem Agenten. Wähle im Produkt unter „Angebote & Quellen“ das passende Angebot. Preise aus den Quellen sind vorläufig; prüfe sie vor dem Kauf beim Agenten.</p><p class="shipping-status">Automatischer Versandvergleich noch nicht aktiv. Die geprüften Rechner berücksichtigen Gewicht, Maße, Route und teilweise Coupons. <a href="https://www.pikobuy.com/shipping-cost" target="_blank" rel="noopener">Pikobuy</a> · <a href="https://www.usfans.com/estimation" target="_blank" rel="noopener">USFans</a> · <a href="https://litbuy.com/shipping-estimate" target="_blank" rel="noopener">Litbuy</a></p>'+(!entries.length?'<p>Noch kein Haul geplant. Öffne ein Produkt und wähle „In den …-Haul“.</p>':entries.map(([id,h])=>{const t=M.haulTotals(h),agent=M.agent(Object.values(h.items)[0].offer);return `<section class="haul"><h2>${esc(agent?.name||id)} <small>${t.quantity} Artikel</small></h2><div class="haulitems">${Object.values(h.items).map(item=>`<article class="haulitem">${mediaUrl(item.image)?`<img src="${esc(mediaUrl(item.image))}" alt="${esc(item.name)}" loading="lazy">`:''}<div><strong>${esc(item.name)}</strong><p>${Number.isFinite(item.offer.euro)?money(item.offer.euro)+' pro Stück':'Preis offen'} · Angebotsstand ${esc(item.offer.checked||'unbekannt')}</p><a href="${esc(M.safe(item.offer.url))}" target="_blank" rel="noopener" referrerpolicy="no-referrer">Gewähltes Angebot ↗</a><label>Anzahl<input type="number" min="1" max="99" step="1" inputmode="numeric" value="${item.quantity}" data-haul-quantity="${esc(item.key)}" data-agent="${esc(id)}"></label><button class="quiet" data-haul-remove="${esc(item.key)}" data-agent="${esc(id)}">Aus Haul entfernen</button></div></article>`).join('')}</div><div class="haulcosts">${[['shipping','Internationaler Versand'],['packing','Packing / Zusatzleistungen'],['domestic','Versand zum Lager'],['fees','Zahlungs- / Agentgebühren'],['taxes','Abgaben, soweit nicht enthalten']].map(([field,label])=>`<label>${label} €<input type="text" inputmode="decimal" placeholder="Noch offen" value="${esc(h[field]??'')}" data-haul-cost="${field}" data-agent="${esc(id)}"></label>`).join('')}</div><p>Bekannter Warenwert: <strong>${money(t.goods)}</strong>${t.unknown?' · '+t.unknown+' Artikel ohne Preis':''}</p><p class="haulsum">${t.total===null?'Gesamt noch offen – fehlende Preise und Kosten ergänzen.':'Geplante Gesamtkosten: '+money(t.total)}</p><div class="costreview">${h.costsStale?`<p class="coststale">Der Inhalt oder die Menge hat sich geändert. Versand und Zusatzkosten erneut prüfen.</p><button data-haul-confirm="${esc(id)}">Kosten für diesen Haul bestätigt</button>`:''}</div><small>Kosten als Gesamtbetrag für diesen Haul eintragen, ausdrücklich 0 für kostenlos oder bereits enthaltene Leistungen. Keine automatische Versandberechnung; Gewicht, Versandlinie und Zusatzleistungen können den Betrag ändern.</small>${renderHaulComparison(id,h)}</section>`}).join(''))}
function renderHaulComparison(id,h){const rows=M.compareHaul(h,groupMap);return `<details class="haulcompare"><summary>Denselben Haul bei anderen Agenten vergleichen</summary><p>Nur Angebote derselben ursprünglichen Produkt-ID. Verglichen wird zunächst der Warenwert. Unterschiedliche Varianten oder Quellpreise bitte prüfen. Ein niedriger Warenwert ist noch kein günstiger Gesamtpreis.</p><div class="tablewrap"><table><thead><tr><th>Agent</th><th>Warenwert</th><th>Abdeckung</th><th></th></tr></thead><tbody>${rows.map(a=>`<tr><td>${esc(a.name)}</td><td>${money(a.goods)}${a.unknown?' + offene Preise':''}</td><td>${a.missing.length?a.missing.length+' Produkte fehlen':'Alle Produkte gefunden'}</td><td>${a.complete&&a.id!==id?`<button data-haul-compare="${esc(id)}" data-target-agent="${esc(a.id)}">Separat planen</button>`:''}</td></tr>`).join('')}</tbody></table></div><p>Versand und Gebühren bleiben je Agent offen, bis passende Tarife bzw. ein konkretes Angebot vorliegen.</p></details>`}
function copyComparedHaul(from,to){const row=M.compareHaul(planning.hauls[from],groupMap).find(a=>a.id===to);if(!row?.complete)return;if(Object.keys(planning.hauls[to]?.items||{}).length){toast('Dieser Agent hat bereits einen Haul. Entferne ihn zuerst oder ändere ihn dort.');return}planning.hauls[to]={items:row.items,shipping:'',packing:'',domestic:'',fees:'',taxes:''};savePlanning();render(false);toast('Derselbe Haul ist separat bei '+row.name+' geplant.')}
const mediaUrl=s=>/^imports\/(media|assets)\/[a-f0-9/]+\.(webp|png|jpe?g|gif)$/.test(s||'')?s:M.safe(s);
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2500)}
function saveFavorites(){try{localStorage.setItem('finds-saved-v2',JSON.stringify(favorites));syncController?.capture();return true}catch{toast('Speichern fehlgeschlagen. Bitte Merkliste exportieren.');return false}}
function toggleSaved(key){const g=groupMap.get(key)||favorites[key];if(!g)return;if(favorites[key]){delete favorites[key];toast('Aus der Merkliste entfernt.')}else{favorites[key]={...g,savedAt:new Date().toISOString()};toast('Auf diesem Gerät gemerkt.')}saveFavorites();render(false);if(detailKey===key)renderDetail()}
function snapshot(){return {category,visible,scroll:window.scrollY,filtersOpen:!$('#filters').hidden,values:Object.fromEntries(['query','brand','subcategory','shop','source','sort','imagefilter'].map(id=>[id,$('#'+id).value]))}}
